example_solution:
class ScrabbleScore {

    private final static letterValues = [
            'D': 2, 'G': 2,
            'B': 3, 'C': 3, 'M': 3, 'P': 3,
            'F': 4, 'H': 4, 'V': 4, 'W': 4, 'Y': 4,
            'K': 5,
            'J': 8, 'X': 8,
            'Q': 10, 'Z': 10
    ].withDefault { 1 }

    static int scoreWord(String word) {
        word.toUpperCase().inject(0) { total, letter ->
            total + letterValues[letter]
        }
    }

}

test_code:
import spock.lang.*

class ScrabbleScoreSpec extends Specification {

    def "Lowercase letter"() {
        expect:
        ScrabbleScore.scoreWord(word) == expected

        where:
        word || expected
        'a'  || 1
    }

    @Ignore
    def "Uppercase letter"() {
        expect:
        ScrabbleScore.scoreWord(word) == expected

        where:
        word || expected
        'A'  || 1
    }

    @Ignore
    def "Valuable letter"() {
        expect:
        ScrabbleScore.scoreWord(word) == expected

        where:
        word || expected
        'f'  || 4
    }

    @Ignore
    def "Empty input"() {
        expect:
        ScrabbleScore.scoreWord(word) == expected

        where:
        word || expected
        ''   || 0
    }

    @Unroll
    @Ignore
    def "Score for word #word should be #expected"() {
        expect:
        ScrabbleScore.scoreWord(word) == expected

        where:
        word                         || expected
        'at'                         || 2
        'zoo'                        || 12
        'street'                     || 6
        'quirky'                     || 22
        'OxyphenButazone'            || 41
        'pinata'                     || 8
        'abcdefghijklmnopqrstuvwxyz' || 87
    }

}
